#define main legacy_main
#include "score-cuda/main.cu"
#undef main
#include <vector>
int main(){const int B=2,C=5,P=1024,K=10;std::vector<float>s(B*C*P);std::vector<int>want,counts(B*C),indices(B*C*K);for(int g=0;g<B*C;g++){for(int i=0;i<P;i++)s[g*P+i]=float((73*i+19*g)%P)/P;std::vector<int>order(P);for(int i=0;i<P;i++)order[i]=i;std::sort(order.begin(),order.end(),[&](int a,int b){return s[g*P+a]>s[g*P+b];});order.resize(K);std::sort(order.begin(),order.end());want.insert(want.end(),order.begin(),order.end());want.push_back(K);}float*S;int*I,*Q;cudaMalloc(&S,s.size()*4);cudaMalloc(&I,indices.size()*4);cudaMalloc(&Q,counts.size()*4);cudaMemcpy(S,s.data(),s.size()*4,cudaMemcpyHostToDevice);auto run=[&](){findTopK<float,2048,256><<<dim3(C,B),256>>>(I,Q,S,.4f,K,C,P);};run();if(cudaDeviceSynchronize()!=cudaSuccess)return 2;for(int trial=1;trial<=5;trial++){cudaMemset(I,0,indices.size()*4);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int rep=0;rep<10;rep++)run();if(cudaDeviceSynchronize()!=cudaSuccess)return 2;double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/10;cudaMemcpy(indices.data(),I,indices.size()*4,cudaMemcpyDeviceToHost);cudaMemcpy(counts.data(),Q,counts.size()*4,cudaMemcpyDeviceToHost);std::vector<int>out;for(int g=0;g<B*C;g++){std::sort(indices.begin()+g*K,indices.begin()+(g+1)*K);out.insert(out.end(),indices.begin()+g*K,indices.begin()+(g+1)*K);out.push_back(counts[g]);}bool ok=out==want;char path[64];snprintf(path,64,"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(out.data(),4,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.15g,\"correct\":%s,\"checked_values\":110,\"max_abs_error\":%d,\"timing_region\":\"approximate_histogram_topk_kernel_mean\",\"jit_excluded\":true,\"internal_repeats\":10,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":110,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",ok?0:1,path);if(!ok)return 1;}cudaFree(S);cudaFree(I);cudaFree(Q);}
